def digest(value):return hashlib.sha256(value.encode()).hexdigest()

def authenticate(connection,credential,purpose,resource,action):
    row=connection.execute("SELECT p.id,p.kind,p.enabled,c.active FROM credentials c JOIN principals p ON p.id=c.principal WHERE c.digest=?",(digest(credential),)).fetchone()
    if not row or not row[2] or not row[3]:raise PermissionError("credential unavailable")
    ident,kind,_,_=row
    if purpose=="interactive":
        if kind!="person":raise PermissionError("machine identities cannot log in interactively")
        return ident
    if purpose!="service" or kind!="service":raise PermissionError("dedicated machine identity required")
    if not connection.execute("SELECT 1 FROM permissions WHERE principal=? AND resource=? AND action=?",(ident,resource,action)).fetchone():raise PermissionError("scope rejected")
    return ident

def session_subject(connection,sid):
    row=connection.execute("SELECT p.id,p.enabled,s.active FROM sessions s JOIN principals p ON p.id=s.principal WHERE s.digest=?",(digest(sid),)).fetchone()
    if not row or not row[1] or not row[2]:raise PermissionError("session unavailable")
    return row[0]

def migrate_consumer(connection,name,new_credential,probe):
    row=connection.execute("SELECT credential,resource,action FROM consumers WHERE name=?",(name,)).fetchone()
    if not row:raise ValueError("unknown consumer")
    identity=authenticate(connection,new_credential,"service",row[1],row[2])
    if probe(new_credential,row[1],row[2])!=identity:raise ValueError("live consumer probe failed")
    with connection:
        changed=connection.execute("UPDATE consumers SET credential=? WHERE name=? AND credential=?",(digest(new_credential),name,row[0])).rowcount
        if changed!=1:raise ValueError("consumer changed concurrently")
    return identity

def offboard(connection,person):
    if connection.execute("SELECT kind FROM principals WHERE id=?",(person,)).fetchone()!=("person",):raise ValueError("only personnel offboarding")
