    with connection:
        connection.execute("UPDATE principals SET enabled=0 WHERE id=?",(person,))
        connection.execute("UPDATE credentials SET active=0 WHERE principal=?",(person,))
        connection.execute("UPDATE sessions SET active=0 WHERE principal=?",(person,))
